(function(){
  const base='http://127.0.0.1:8737';
  const log=(kind,data)=>fetch(base+'/log',{method:'POST',body:JSON.stringify({t:Date.now(),kind,data})}).catch(()=>{});
  let n=0;
  const wrap=()=>{
    const b=window.__jusprinBridge;
    if(!b||b.__wrapped){return;}
    const orig=b.deliver; b.deliver=(env)=>{ try{ if(env&&['printers','state','printer_error','bridge_error','screen','confirm'].includes(env.type)) log('deliver',env);}catch(e){} return orig(env); };
    b.__wrapped=true; log('wrapped',{});
  };
  setInterval(wrap,200);
  setInterval(async()=>{
    try{
      const r=await fetch(base+'/cmd'); const txt=await r.text(); if(!txt) return;
      const cmd=JSON.parse(txt);
      if(cmd.snap){ log('snap',document.documentElement.outerHTML); return; }
      if(cmd.click){ const el=[...document.querySelectorAll(cmd.click)].find(e=>!cmd.text||e.textContent.includes(cmd.text)); log('click',{found:!!el,html:el?el.outerHTML.slice(0,300):null}); if(el) el.click(); return; }
      const env={protocol:'jusprin-home-bridge',version:1,id:'probe-'+(n++),type:cmd.type,payload:cmd.payload||{}};
      window.wx.postMessage(JSON.stringify(env)); log('sent',env);
    }catch(e){ log('error',String(e)); }
  },500);
})();
